  FT["PH-H1576"] = {"id":"PH-H1576","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1957/ra_1742_1957.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Macrohon市","en":"An Act Creating Certain Barrios in the Municipality of Macrohon, Province of Leyte","orig":"An Act Creating Certain Barrios in the Municipality of Macrohon, Province of Leyte"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1742","issuingBody":"Congress of the Philippines","promulgatedDate":"1957-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1957/ra_1742_1957.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1576-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The following barrios are created in the Municipality of Macrohon, Province of Leyte, to be constituted as follows:\nBarrio of Ilihan shall be composed of the sitios of Ilihan Proper, Camalig, Sindangan, Gawisan, Guinabonan, Lunang, Mabanga and Danao;\nBarrio Villa Jacinta shall be composed of the sitios of Upper Villa Jacinta Proper, Peng-on, Mahayahay, Canodto, Laray, Luan, Santa Rosa and Camangahan; and Barrio Lower Villa Jacinta shall be composed of the sitios of Lower Villa Jacinta Proper, Suba, Central, Babayon, Muldes, Boayahan and Pancil."}},{"id":"PH-H1576-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1957."}}],"pack":"ph-p22"};
