  FT["PH-H1579"] = {"id":"PH-H1579","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1957/ra_1745_1957.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Declaring October Twenty of Every Year a Special Holiday in the Province of Leyte, Amending for the Purpose Section Thirty of the Revised Administrative Code","orig":"An Act Declaring October Twenty of Every Year a Special Holiday in the Province of Leyte, Amending for the Purpose Section Thirty of the Revised Administrative Code"},"level":"law","status":"active","topics":["administrative"],"docNumber":"Republic Act No. 1745","issuingBody":"Congress of the Philippines","promulgatedDate":"1957-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1957/ra_1745_1957.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1579-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section thirty of the Revised Administrative Code is amended to read as follows:\n\"Sec. 30. Special holiday declared by the President of the Philippines. — The President of the Philippines may, in his discretion, proclaim any other day a special public holiday for a particular date, and in calling a special election for a member of the Congress of the Philippines, or for a provincial office he shall limit such holiday, if one is declared, to the particular district, or province where the election is held: Provided, That October twenty of every year shall be a special holiday in the Province of Leyte.\""}},{"id":"PH-H1579-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1957."}}],"pack":"ph-p22"};
