  FT["PH-H1601"] = {"id":"PH-H1601","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1957/ra_1767_1957.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Tiaong市","en":"An Act Creating the Barrio of Bucal in the Municipality of Tiaong, Province of Quezon","orig":"An Act Creating the Barrio of Bucal in the Municipality of Tiaong, Province of Quezon"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1767","issuingBody":"Congress of the Philippines","promulgatedDate":"1957-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1957/ra_1767_1957.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1601-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sitio of Bucal in the Municipality of Tiaong, Province of Quezon, is separated from the barrio of Bula, and is constituted into a new barrio in the said municipality to be known as the Barrio of Bucal."}},{"id":"PH-H1601-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1957."}}],"pack":"ph-p22"};
  FT["PH-H1602"] = {"id":"PH-H1602","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1957/ra_1768_1957.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act to Amend Republic Act Numbered One Thousand Three Hundred Ninety-Two, Entitled “An Act to Amend Section Eleven of the Philippine Tariff Act of 1909 and Exempting Textiles Made of One Hundred Per Cent Philippine Ramie Fiber from the Payment of Duty to Provide Incentives for the Development of the Ramie Industry”","orig":"An Act to Amend Republic Act Numbered One Thousand Three Hundred Ninety-Two, Entitled “An Act to Amend Section Eleven of the Philippine Tariff Act of 1909 and Exempting Textiles Made of One Hundred Per Cent Philippine Ramie Fiber from the Payment of Duty to Provide Incentives for the Development of the Ramie Industry”"},"level":"law","status":"active","topics":["tax"],"docNumber":"Republic Act No. 1768","issuingBody":"Congress of the Philippines","promulgatedDate":"1957-06-21","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1957/ra_1768_1957.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1602-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section one of Republic Act Numbered One thousand three hundred ninety-two is amended to read as follows:\n\"Sec. 1. Ramie threads, yarns, textiles and industrial fabrics hereinafter also called ramie goods, when processed abroad from one hundred per cent ramie fiber grown in the Philippines and brought direct from the farmer-producers or from any of their cooperatives by any government agency designated by the President of the Philippines and by it exported abroad in exchange therefor when their importation is made through the government agency so designated by the President shall be exempt from the payment of customs duties under the tariff laws in force and the special import tax under Republic Act Numbered One thousand three hundred ninety-four: Provided, That such tax-exempt importation herein contemplated shall be allocated proportionately among the original farmer-producers or any of their cooperatives from whom the government agency herein specified obtained the ramie fiber for processing abroad.\n\"The exemption above granted shall cease two years after the date of approval of this amendatory Act or at any earlier date upon proclamation by the President, upon recommendation of the National Economic Council, to the effect that sufficient degumming, spinning and/or weaving mills to process the entire production of ramie fiber have been established in the country.\""}},{"id":"PH-H1602-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The title of Republic Act Numbered One thousand three hundred ninety-two is amended to read as follows:\n\"An Act exempting textiles made of one hundred per cent Philippine ramie fiber from the payment of duty and the special import tax to provide incentives for the development of the ramie industry.\""}},{"id":"PH-H1602-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1957."}}],"pack":"ph-p22"};
